class Solution {
  private int n;
  private int[] first, last, cnt;
  private long[] pairSum;
  private int[] a;

  private boolean isPeak(int k) {
    return k > 0 && k < n - 1 && a[k] > a[k - 1] && a[k] > a[k + 1];
  }

  private void pull(int node) {
    int l = 2 * node, r = 2 * node + 1;
    cnt[node] = cnt[l] + cnt[r];
    first[node] = cnt[l] > 0 ? first[l] : first[r];
    last[node] = cnt[r] > 0 ? last[r] : last[l];
    pairSum[node] = pairSum[l] + pairSum[r];
    if (cnt[l] > 0 && cnt[r] > 0) pairSum[node] += (long) (first[r] - last[l]) * last[l];
  }

  private void build(int node, int lo, int hi) {
    if (lo == hi) {
      set(node, lo);
      return;
    }
    int mid = (lo + hi) >>> 1;
    build(2 * node, lo, mid);
    build(2 * node + 1, mid + 1, hi);
    pull(node);
  }

  private void set(int node, int pos) {
    if (isPeak(pos)) {
      cnt[node] = 1;
      first[node] = last[node] = pos;
    } else {
      cnt[node] = 0;
    }
    pairSum[node] = 0;
  }

  private void update(int node, int lo, int hi, int pos) {
    if (lo == hi) {
      set(node, pos);
      return;
    }
    int mid = (lo + hi) >>> 1;
    if (pos <= mid) update(2 * node, lo, mid, pos);
    else update(2 * node + 1, mid + 1, hi, pos);
    pull(node);
  }

  private int accCnt, accFirst, accLast;
  private long accSum;

  private void query(int node, int lo, int hi, int l, int r) {
    if (r < lo || hi < l || cnt[node] == 0) return;
    if (l <= lo && hi <= r) {
      if (accCnt == 0) {
        accFirst = first[node];
      } else {
        accSum += (long) (first[node] - accLast) * accLast;
      }
      accSum += pairSum[node];
      accLast = last[node];
      accCnt += cnt[node];
      return;
    }
    int mid = (lo + hi) >>> 1;
    query(2 * node, lo, mid, l, r);
    query(2 * node + 1, mid + 1, hi, l, r);
  }

  public long[] countOfPeaks(int[] nums, int[][] queries) {
    n = nums.length;
    a = nums.clone();
    first = new int[4 * n];
    last = new int[4 * n];
    cnt = new int[4 * n];
    pairSum = new long[4 * n];
    build(1, 0, n - 1);
    int count = 0;
    for (int[] q : queries) if (q[0] == 1) count++;
    long[] ans = new long[count];
    int idx = 0;
    for (int[] q : queries) {
      if (q[0] == 2) {
        a[q[1]] = q[2];
        for (int k = Math.max(0, q[1] - 1); k <= Math.min(n - 1, q[1] + 1); k++)
          update(1, 0, n - 1, k);
      } else {
        int l = q[1], r = q[2];
        accCnt = 0;
        accSum = 0;
        if (l + 1 <= r - 1) query(1, 0, n - 1, l + 1, r - 1);
        if (accCnt == 0) {
          ans[idx++] = 0;
        } else {
          long total =
              accSum - (long) l * (accLast - accFirst) + (long) (r - accLast) * (accLast - l);
          ans[idx++] = total;
        }
      }
    }
    return ans;
  }
}
